PreInvocation.command:
python3 -c 'import json, subprocess; required={"filipkrawiec-orchestration", "filipkrawiec-core", "filipkrawiec-workflow", "filipkrawiec-authoring"}; missing=[];
try:
  installed={plugin.get("name") for plugin in json.loads(subprocess.check_output(["agy", "plugin", "list"], text=True, stderr=subprocess.DEVNULL)).get("imports", [])}
  missing=sorted(required-installed)
except Exception:
  pass
print(json.dumps({"injectSteps":[{"ephemeralMessage":"Orchestration notice: missing companion plugins: " + ", ".join(missing)}]} if missing else {}))'
